schemas.schema-01-todo.prisma:
/// User profile information for single-device personal task management.
///
/// Stores basic user information entered during initial welcome screen
/// setup. Each user represents the current device's user profile, with no
/// external authentication required. This model supports the single-user
/// experience by tracking name, email, and derived username for task
/// organization.
///
/// The model assumes a single user per device with no session or login
/// functionality, keeping the application minimal as required.
///
/// @namespace ToDo
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_users {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// User's full name
  name String

  /// User's email address used for profile identification. Must be unique
  /// across all users.
  email String

  /// Derived username based on email. Format: first.last from email address.
  username String

  /// Timestamp when the user profile was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp of the last update to the user profile.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the user profile was soft-deleted (if applicable).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  todo_tasks todo_tasks[]

  @@unique([email])
}

/// Todo items created and managed by the user for personal task tracking.
///
/// Stores individual task items with their titles, completion status, and
/// creation timestamps. Each task belongs to a user profile and follows the
/// minimal requirements of having a title (3-200 characters) and a
/// completion flag.
///
/// Tasks are managed independently with no categories or due dates, matching
/// the application's focus on simplicity. Tasks automatically disappear from
/// the active list when marked complete.
///
/// @namespace ToDo
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_tasks {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// User who created the task. {@link todo_users.id}
  todo_user_id String @db.Uuid

  /// Task title as provided by the user. Must be between 3-200 characters.
  title String

  /// Indicates if the task is completed. True = completed, False = pending.
  completed Boolean

  /// Timestamp when the task was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp of the last update to the task.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the task was soft-deleted (if applicable).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  user todo_users @relation(fields: [todo_user_id], references: [id], onDelete: Cascade)

  @@index([todo_user_id, completed])
}

schemas.main.prisma:
generator client {
  provider        = "prisma-client-js"
  engineType      = "client"
  previewFeatures = ["postgresqlExtensions", "views"]
}
datasource db {
  provider   = "postgresql"
  url        = env("DATABASE_URL")
  extensions = [pg_trgm]
}
generator markdown {
  provider = "prisma-markdown"
  output   = "../../docs/ERD.md"
}

